window.OPS_LESSONS = [{"id":"612r-controls-tour","title":"Know your 612R cab: CommandARM, multi-function lever and corner post","minutes":16,"objective":"Learn what every main control on the 612R multi-function lever and CommandARM does and where it sits, read the corner post display, open Controls Setup, then find and press each control on demand without help.","trainer":"Machine parked: lever in PARK, engine running at low idle, boom unfolded, solution pump and spray system off, park brake switch released (P light off), Transport Lock off, foot off the boom fold switch, speed range wheel at its lowest. Have figure NX711654 (lettered multi-function lever) ready.","sections":[{"title":"1. The multi-function lever","mode":"learn","checkpoint":false,"steps":[{"id":"lever-layout","say":"Rest your hand on the multi-function lever and match its buttons to the lettered drawing beside this step.","why":"Forward drives, back reverses, the middle is neutral; the buttons run spraying, boom and guidance.","figure":"NX711654","draft":false,"confirm":["Lever layout matched to the drawing"]},{"id":"hms","say":"Press HMS, the button marked HMS at the top right of the lever.","why":"HMS runs several machine systems with one press when you leave a headland.","figure":"N152638","draft":false,"confirm":[]},{"id":"centre-boom","say":"Push the top of the round centre boom switch, then the bottom.","why":"Top raises the boom centre section, bottom lowers it.","figure":"N152641","draft":false,"confirm":[]},{"id":"tilt-left","say":"Left wing: push the top of the left tilt rocker, then the bottom.","why":"Top raises the left-hand boom sections, bottom lowers them.","figure":"N152642","draft":false,"confirm":[]},{"id":"tilt-right","say":"Right wing: push the top of the right tilt rocker, then the bottom.","why":"Top raises the right-hand boom sections, bottom lowers them.","figure":"N152643","draft":false,"confirm":[]},{"id":"ibs-right","say":"A waterway angles in from the left. Press IBS Right once to shut off the left outer section.","why":"IBS Right shuts sections off one at a time, starting at the left-hand end of the boom.","figure":"N155496","draft":false,"confirm":[]},{"id":"ibs-left-reset","say":"Now press IBS Left once, then IBS Reset to turn the shut-off sections back on.","why":"IBS Left starts at the right-hand end; Reset restarts all shut-off sections that are enabled.","figure":"N153020","draft":false,"confirm":[]},{"id":"master-spray","say":"Press the yellow Spray System On/Off button to turn spraying on, then press it again for off.","why":"It turns enabled boom sections on and off; its indicator lights while it's on.","figure":"N152644","draft":false,"confirm":[]},{"id":"auto-resume","say":"Press AutoTrac Resume (marked AUTO), then BoomTrac Resume just to its right.","why":"AUTO activates AutoTrac steering; the other one hands boom height back to BoomTrac.","figure":"NX711654","draft":true,"confirm":[]},{"id":"quick-stop","say":"Press the yellow Quick Stop switch on top of the lever, then release it.","why":"It shuts off the solution pump, spray system and wet valves at once; you still pull the lever back.","figure":"N152634","draft":true,"confirm":[]},{"id":"speed-wheel","say":"Roll the speed range wheel up a few clicks to raise the target speed.","why":"The wheel sets target speed; you can change it moving or stopped.","figure":"N152647","draft":false,"confirm":[]},{"id":"configurable","say":"Press any one of the configurable buttons A, B, C or D on the side of the lever.","why":"They run what you assign in Controls Setup; there are no default assignments.","figure":"NX707641","draft":true,"confirm":[]}]},{"title":"2. CommandARM switches, corner post and Controls Setup","mode":"learn","checkpoint":false,"steps":[{"id":"engine-idle","say":"Press High Idle, then Low Idle, on the CommandARM's engine switches.","why":"High Idle gives maximum engine speed, Low Idle minimum engine speed.","figure":"N151286","draft":false,"confirm":[]},{"id":"park-brake-switch","say":"Press Park Brake (P) to engage the park brakes, then press it again to release them.","why":"Brakes set with this switch never release by themselves; release it before you drive.","figure":"N120664","draft":false,"confirm":[]},{"id":"transport-lock","say":"Find the Transport Lock switch with the engine switches. Press it on, then off.","why":"On the road it blocks spray on/off, boom moves and tread adjust; the pump can still run.","figure":"N120615","draft":true,"confirm":["Transport Lock found, left off"]},{"id":"corner-post","say":"On the corner post display, find vehicle speed, the transmission set speed, the gear and the park brake light.","why":"They show what the machine is doing; a lit red brake warning means stop at once.","figure":"H137356","draft":false,"confirm":["Corner post indicators found"]},{"id":"controls-setup","say":"Press Controls Setup on the navigation bar below the display and open the Multi-Function Lever tab.","why":"No default assignments; the buttons relock at every key cycle until you unlock them.","figure":"H118151C","draft":false,"confirm":["Controls Setup opened"]}]},{"title":"3. Find it","mode":"practice","checkpoint":false,"steps":[{"id":"find-right-wing","say":"A post is coming up under the right wing. Lift the right wing now.","why":"Right-hand boom tilt raises only the right-hand boom sections.","figure":"N152643","draft":true,"confirm":[]},{"id":"find-ibs-left","say":"A point row closes in from the right. Shut off one section, starting at the right-hand end.","why":"IBS lets you shut sections in sequence without taking your hand off the lever.","figure":"N152636","draft":true,"confirm":[]},{"id":"find-field-2","say":"Road ahead. Swap the set speed to Field 2, the one that reaches transport speeds.","why":"Field 1 is limited to the maximum field speed; transport speeds need Field 2.","figure":"N152647","draft":true,"confirm":[]},{"id":"find-quick-stop","say":"Emergency! Shut off the solution pump, spraying and wet valves with one switch, then release it.","why":"Quick Stop stops them all at once; you still pull the lever back to stop the machine.","figure":"N152634","draft":true,"confirm":[]}]},{"title":"4. Prove it","mode":"assess","checkpoint":false,"steps":[{"id":"prove-spray","say":"Turn spraying on, then off again.","why":"Spray System On/Off turns the enabled boom sections on and off.","figure":"N152644","draft":true,"confirm":[]},{"id":"prove-left-wing","say":"Raise the left wing.","why":"Left tilt up raises the left-hand boom sections.","figure":"N152642","draft":true,"confirm":[]},{"id":"prove-sections","say":"Turn every shut-off boom section back on with one press.","why":"IBS Reset restarts all shut-off sections that are enabled.","figure":"N152635","draft":true,"confirm":[]}]}]},{"id":"612r-drive-transport","title":"Drive in Auto mode and transport safely","minutes":17,"objective":"Move off in Auto mode in the manual's order, slow and stop with the lever before the pedal, back up, park and shut down safely, prepare the machine for the road and drive off in transport mode, then park again without help.","trainer":"Field edge after spraying: boom unfolded, solution pump and spray system off, engine running at low idle, lever in PARK, park brake switch engaged (P light on; press Park Brake once if it is off), Transport Lock off, ladder up, speed range wheel at its lowest, wheels straight, transmission mode on the display set to Manual. The tread is already at its narrowest.","sections":[{"title":"1. Move off in Auto mode","mode":"learn","checkpoint":false,"steps":[{"id":"auto-mode","say":"On the display open Menu, Machine Settings, Transmission, and select Auto.","why":"The machine always starts in Manual mode until you select Auto and press High Idle.","figure":"N142909","draft":false,"confirm":["Auto selected on the display"]},{"id":"high-idle","say":"Press the High Idle switch for maximum engine speed.","why":"Auto mode is fully active only with Auto selected and the engine at high idle.","figure":"N137031","draft":false,"confirm":[]},{"id":"release-park-brake","say":"Press the Park Brake switch to release the park brakes.","why":"Brakes set with this switch don't release by themselves when you move the lever.","figure":"N137032","draft":false,"confirm":[]},{"id":"move-off","say":"Check around the machine, then move the lever out of PARK and push it slowly forward.","why":"Auto mode raises engine rpm and shifts the transmission for you as needed.","figure":"N166439","draft":false,"confirm":[]},{"id":"target-speed","say":"Roll the speed range wheel up a few clicks to raise the target speed.","why":"The corner post shows target and vehicle speed; with the lever fully forward, Auto holds the target.","figure":"N166440","draft":false,"confirm":[]}]},{"title":"2. Slow, stop, back up and park","mode":"learn","checkpoint":false,"steps":[{"id":"slow-stop","say":"Pull the lever back to neutral, then press the brake pedal to stop completely.","why":"The lever does the main braking; braking with the pedal instead wears the brakes early.","figure":"N166476","draft":false,"confirm":["Stopped with the brake pedal"]},{"id":"back-up","say":"Check behind you. Move the lever right and rearward to back up a short way, then return it to neutral.","why":"Reverse speed follows how far you move the lever; the backup alarm warns people nearby.","figure":"N155115","draft":false,"confirm":[]},{"id":"lever-park","say":"Slowly return the lever to the PARK position.","why":"In PARK the park brakes apply automatically; never park with the secondary brake.","figure":"N166477","draft":false,"confirm":[]},{"id":"brake-switch-on","say":"Press the Park Brake switch so a bumped lever can't move the machine.","why":"Optional in PARK, but it holds the machine; remember it must be released by hand later.","figure":"N137032","draft":false,"confirm":[]},{"id":"low-idle","say":"Press Low Idle to bring the engine down to low idle.","why":"The manual's parking order: lever in PARK, then low idle, then lights off and key.","figure":"N166477","draft":false,"confirm":[]},{"id":"shut-down","say":"Turn off lights and accessories, then turn the key to OFF and remove it.","why":"After working load, idle at least 2 minutes first to cool the hot engine parts.","figure":"H127222","draft":false,"confirm":["Lights off, key OFF and removed"]},{"id":"ladder-down","say":"Lower the ladder with the Ladder Up/Down switch.","why":"It's the last step of parking; on the machine the ladder also lowers when shut off.","figure":"N151287","draft":false,"confirm":[]}]},{"title":"3. Ready for the road","mode":"learn","checkpoint":false,"steps":[{"id":"smv-start","say":"Check the SMV emblem is on the boom, then start the engine from the seat, lever in PARK.","why":"The emblem warns traffic; an engine that starts out of PARK has a starting-circuit fault.","figure":"N155495","draft":false,"confirm":["SMV emblem in place","Engine started, lever in PARK"]},{"id":"lights","say":"Press Road Lights and Hazard Lights, then check the amber warning lights are flashing.","why":"Lights and the SMV emblem warn other traffic, day or night.","figure":"N153023","draft":false,"confirm":["Road and hazard lights on, amber lights flashing"]},{"id":"tread","say":"Check the tread is at its narrowest setting before the road.","why":"Always transport at the narrowest tread; top transport speeds need it.","figure":"N120613","draft":false,"confirm":["Tread at narrowest"]},{"id":"fold","say":"Fold the boom: hold the fold foot switch and hold centre boom raise until it's in the cradles.","why":"Booms move quickly, so keep everyone clear; off the cradles, transport can damage the machine.","figure":"WZ1409986","draft":false,"confirm":[]},{"id":"transport-lock","say":"Press the Transport Lock switch to put the machine in transport mode.","why":"It blocks spray on/off, boom moves and tread adjust on the road; its light shows it's on.","figure":"N120615","draft":true,"confirm":["Transport Lock on"]},{"id":"high-idle-road","say":"Press High Idle for maximum engine speed.","why":"Maximum engine speed before you move off; Auto mode needs it to be fully active.","figure":"N137031","draft":false,"confirm":[]},{"id":"field-2","say":"Press the speed range wheel in to switch to Field 2 for transport speeds.","why":"Field 1 stops at maximum field speed. Unless the application system is empty, don't exceed 48 km/h (30 mph).","figure":"N152647","draft":false,"confirm":[]},{"id":"release-drive","say":"Release the Park Brake switch, then push the lever slowly forward onto the road.","why":"Switch-set brakes stay on until released. Before a downhill, choose a speed for the load and slope.","figure":"N137032","draft":false,"confirm":[]}]},{"title":"4. Arrive and park (no help)","mode":"assess","checkpoint":false,"steps":[{"id":"arrive-stop","say":"You're at the yard. Slow down with the lever and stop in PARK.","why":"Stop slowly to avoid nose diving; the lever does the main braking.","figure":"N166477","draft":false,"confirm":[]},{"id":"arrive-secure","say":"Secure it: Park Brake switch on, then Low Idle.","why":"A bumped lever can't move the machine, and the engine comes down to idle.","figure":"N166477","draft":false,"confirm":[]},{"id":"arrive-shut-down","say":"Shut down: lights off, then key OFF and removed.","why":"Remove the key whenever you leave the machine unattended.","figure":"H127222","draft":false,"confirm":["Lights off, key OFF and removed"]}]}]},{"id":"612r-fill-load","title":"Fill the solution tank and load chemicals safely","minutes":18,"objective":"Park at the fill site and protect yourself, fill an empty 612R solution tank from a nurse tank with the sprayer pump, load the chemical through the eductor in the manual's order (and recover when it won't draw), finish the fill, mix with agitation from the cab, then repeat the eductor load with a full tank.","trainer":"Boom folded, engine running at low idle, solution pump off, park brake switch off, wheel straight. Lever just out of the park slot and slightly forward: the sprayer is creeping up to the nurse tank. The solution tank is empty and the product label is at hand.","sections":[{"title":"1. Park at the fill site and protect yourself","mode":"learn","checkpoint":false,"steps":[{"id":"park","say":"You're creeping up to the nurse tank. Stop: bring the multi-function lever back into PARK.","why":"The park brakes apply automatically when the lever is in PARK.","figure":"N166477","draft":false,"confirm":[]},{"id":"park-brake","say":"Press the Park Brake switch so a bumped lever can't move the machine while you fill.","why":"The manual allows the park brake switch for exactly this; it must be released before you drive.","figure":"N137032","draft":false,"confirm":[]},{"id":"label-ppe","say":"Read the chemical label's directions, then put on the protective equipment the label lists.","why":"Chemicals can poison and injure; the label sets your PPE. Don't rely on the cab to protect you.","figure":"A34471","draft":false,"confirm":["Label read, PPE on"]}]},{"title":"2. Connect the nurse tank and start the fill","mode":"learn","checkpoint":false,"steps":[{"id":"pump-dry-check","say":"Check the fill hose is as short as possible and the nurse tank level is above the solution pump's midline.","why":"A solution pump that runs dry is damaged; the level must stay there for the whole fill.","figure":"N87475","draft":false,"confirm":["Short hose, nurse level above pump midline"]},{"id":"quikfill-closed","say":"Check the side Quik-Fill valve is closed, then open the lock levers and remove the cap.","why":"The Quik-Fill valve can hold hazardous material: it must be closed before the cap comes off.","figure":"NX1435337","draft":false,"confirm":["Quik-Fill closed, cap off"]},{"id":"connect-hose","say":"Connect the nurse tank fill hose to the Quik-Fill adapter and close the lock levers.","why":"Hose on and locked before any valve opens: manual step 3.","figure":"NX1435337","draft":false,"confirm":["Hose connected, levers closed"]},{"id":"prime-if-empty","say":"The sight gauge reads empty. Prime the pump first: run a low volume rinse cycle, then end it.","why":"An empty tank lets the pump run dry; the rinse can end once the pump is primed.","figure":"NX1434992","draft":false,"confirm":["Pump primed"]},{"id":"start-pull-fill","say":"Open the nurse tank valve. Press Pull-On Fill on the keypad, then open the Quik-Fill valve.","why":"Manual order (steps 4-5). Pressing Pull-On Fill again stops the fill.","figure":"NX1435136","draft":false,"confirm":["Nurse valve open, Pull-On Fill on, Quik-Fill open"]},{"id":"auto-fill","say":"On the front micro display select Fill menu, then Pull-on fill, then Tank auto fill.","why":"Auto fill shuts down by itself when the upper tank level switches are reached.","figure":"NX1440374","draft":false,"confirm":["Tank auto fill running"]}]},{"title":"3. Load the chemical through the eductor","mode":"learn","checkpoint":false,"steps":[{"id":"eductor-down","say":"Lift the eductor slightly, pull the handle to unlatch it, lower it and raise the lid.","why":"Manual steps 9-10: the hopper is lowered and opened before the eductor is started.","figure":"N98892","draft":false,"confirm":["Eductor lowered, lid up"]},{"id":"half-full","say":"The tank is only a quarter full. Wait until it is at least half full, then press Eductor On/Off.","why":"Starting the eductor before half full makes the chemical foam.","figure":"NX1435325","draft":false,"confirm":["Half full, eductor on"]},{"id":"eductor-valves","say":"Open the eductor sump valve (handle parallel with the hose), then the rinse valve (turn clockwise).","why":"The sump valve lets the hopper be drawn into the tank; the rinse valve washes the hopper.","figure":"N135935","draft":false,"confirm":["Sump and rinse valves open"]},{"id":"pour","say":"Pour the label's measured amount of chemical into the eductor hopper.","why":"The label sets the amount; the poly eductor's level gauge helps you fill.","figure":"N155780","draft":false,"confirm":["Chemical poured"]},{"id":"not-drawing","say":"Chemical isn't drawn in. Valves are open, engine at low idle: take off your PPE and climb into the cab.","why":"Engine speed too low is a listed cause. PPE comes off before you re-enter the cab.","figure":null,"draft":true,"confirm":["PPE off, in the cab"]},{"id":"high-idle","say":"Press High Idle to raise engine speed for the eductor.","why":"Eductor table: engine speed too low, increase to 1800 rpm minimum (manual controls only).","figure":"N137031","draft":true,"confirm":[]},{"id":"rinse-container","say":"PPE back on, at the eductor: rinse the empty container over the rinse nozzle by pushing it down.","why":"The rinse goes into the tank; the manual says to triple rinse empty containers before disposal.","figure":"N135936","draft":false,"confirm":["Container rinsed"]},{"id":"close-valves","say":"Check the hopper is empty, then close the eductor rinse valve and the sump valve.","why":"A hopper raised with chemical still in it spills.","figure":"N135935","draft":false,"confirm":["Hopper empty, valves closed"]},{"id":"stow-eductor","say":"Close the hopper lid, lift the eductor back up, then press Eductor On/Off to stop it.","why":"Manual steps 19-20: stow the eductor, then switch it off.","figure":"NX1435325","draft":false,"confirm":["Eductor stowed and off"]}]},{"title":"4. Finish the fill and mix","mode":"learn","checkpoint":false,"steps":[{"id":"close-fill","say":"Auto fill has stopped. Close the nurse tank and Quik-Fill valves, then remove the hose and refit the cap.","why":"Auto fill stops at the upper tank level switches; valves are closed before the hose comes off.","figure":"NX1435337","draft":false,"confirm":["Valves closed, hose off, cap on"]},{"id":"tank-volume","say":"Back in the cab with PPE off: on the Tank System page, set the Tank Fill Volume preset.","why":"Without it the displayed tank volume and the low tank alarm are wrong.","figure":"N158676","draft":false,"confirm":["Tank Fill Volume set"]},{"id":"pump-on","say":"Start mixing: press Solution Pump on the CommandARM.","why":"Agitation only works with the solution pump running.","figure":"N155117","draft":false,"confirm":[]},{"id":"agitation","say":"Press Agitation on the CommandARM and mix thoroughly before you go to the field.","why":"Pump speed and agitation level set how hard it mixes; a lower rate foams less.","figure":"N120490","draft":false,"confirm":["Agitation on"]},{"id":"release-park-brake","say":"Ready to leave the fill site: release the Park Brake switch before the lever leaves PARK.","why":"Brakes set with the switch do not release by themselves when you move the lever.","figure":"N137032","draft":false,"confirm":[]}]},{"title":"5. Practice: next load, tank already full of water","mode":"practice","checkpoint":false,"steps":[{"id":"p-eductor-level","say":"Next load: the tank holds water only and this product foams. Set Eductor Level to Low first.","why":"Low eductor suction reduces chemical foaming while loading.","figure":"WZ1406991","draft":false,"confirm":["Eductor Level Low"]},{"id":"p-open-load","say":"PPE on. Quik-Fill closed, eductor down and lid up, Eductor On/Off on, sump then rinse valve open.","why":"The full tank must still have room for the chemical; a full tank slows the eductor somewhat.","figure":"N135935","draft":false,"confirm":["Eductor running, valves open"]},{"id":"p-pour-rinse","say":"Pour the chemical in, then rinse the empty container over the rinse nozzle.","why":"Rinse the empty container on the nozzle, as before.","figure":"N135936","draft":false,"confirm":["Poured and container rinsed"]},{"id":"p-close","say":"Hopper empty? Close rinse then sump valve, close the lid, lift the eductor, press Eductor On/Off.","why":"An empty hopper doesn't spill when it is lifted.","figure":"NX1435325","draft":false,"confirm":["Eductor closed down"]}]}]},{"id":"612r-boom-handling","title":"Unfold, level and protect the boom","minutes":16,"objective":"Unfold the 612R boom safely (overhead lines, people, Transport Lock), recover an unfold that stops part way, set the height and level the wings, switch BoomTrac on and make it Active, handle a post, a fence line and a boom breakaway, then fold onto the cradles for transport.","trainer":"Boom folded on its cradles, lever in the park slot, wheel straight, engine running. Tell the trainee the Transport Lock is still on from the road trip, the field has less than 30% crop canopy, and there are no overhead lines at this entrance.","sections":[{"title":"1. Before the boom moves","mode":"learn","checkpoint":false,"steps":[{"id":"look-around","say":"At the field entrance, look up and around: no overhead wires near the boom, nobody in its fold area.","why":"Never fold or unfold near overhead wires; booms move quickly and can kill.","figure":"N44191","draft":false,"confirm":["No wires, nobody near, room to unfold"]},{"id":"transport-lock-off","say":"The Transport Lock is still on from the road. Press Transport Lock so its indicator goes off.","why":"With the Transport Lock on, the boom can't fold, unfold, raise, lower or tilt.","figure":"N120615","draft":false,"confirm":["Transport Lock indicator off"]}]},{"title":"2. Unfold, recover and set the height","mode":"learn","checkpoint":false,"steps":[{"id":"unfold","say":"Hold the boom fold/unfold floor switch and hold Centre boom lower until both sides are fully unfolded.","why":"With the floor switch held, the centre boom switch folds and unfolds instead of moving the frame.","figure":"N153423","draft":false,"confirm":[]},{"id":"retry-unfold","say":"The right outer section stopped part way out. Fold the boom fully, then unfold it again.","why":"The manual's fix when an outer section stops part way: fold the boom and retry the unfold.","figure":"N153424","draft":false,"confirm":[]},{"id":"lower-to-height","say":"Foot off the floor switch. Press Centre boom lower until the tips are at spraying height.","why":"Flat fan tips usually sit 457\u2014559 mm (18\u201422 in) above the target; too high drifts.","figure":"N153423","draft":false,"confirm":[]},{"id":"level-wings","say":"Lower the left wing, then the right wing, to the desired height.","why":"Each wing has its own boom switch; a wing left high sprays wide and drifts.","figure":"N153423","draft":false,"confirm":[]}]},{"title":"3. Let BoomTrac hold the height","mode":"learn","checkpoint":false,"steps":[{"id":"resume-try","say":"Press BoomTrac Resume on the handle to let BoomTrac hold the boom height.","why":"BoomTrac controls the centre frame and tilts to follow the ground or crop.","figure":"NX711654","draft":false,"confirm":[]},{"id":"boomtrac-on","say":"Diagnostics opened and the status is grey: BoomTrac is OFF. Switch BoomTrac ON on the BoomTrac tab.","why":"Grey means disabled; Diagnostics marks each unmet prerequisite with an exclamation mark.","figure":"WZ1407986","draft":false,"confirm":["BoomTrac switched ON"]},{"id":"sensor-target","say":"This crop covers less than 30% of the ground. Set Sensor Target to Ground.","why":"Ground reads the soil surface: the most accurate choice when canopy is minimal.","figure":"NX1458211","draft":false,"confirm":["Sensor Target: Ground"]},{"id":"height-target","say":"Keep Height Mode Locked and enter the centre Target Height for your spray tips.","why":"Locked keeps the whole boom at one height: best for coverage and drift control.","figure":"NX1458247","draft":false,"confirm":["Locked, target height set"]},{"id":"resume-active","say":"Status now green, Ready. Press BoomTrac Resume again: the status should read Active.","why":"Ready means press Resume to activate; Active means BoomTrac is holding the height.","figure":"NX711654","draft":false,"confirm":[]}]},{"title":"4. In the field: a post, a fence and a breakaway","mode":"learn","checkpoint":false,"steps":[{"id":"drive","say":"Drive on: lever out of PARK and forward.","why":"Judge BoomTrac on the move; a parked boom bouncing a little is normal.","figure":"N152958","draft":false,"confirm":[]},{"id":"post-raise","say":"A post stands in the right wing's path. Raise the right wing now.","why":"The top of the right boom switch raises the right-hand boom sections clear.","figure":"N152643","draft":true,"confirm":[]},{"id":"post-lower","say":"Past the post: lower the right wing back to working height.","why":"A boom set excessively above the target increases the risk of spray drift.","figure":"N152643","draft":true,"confirm":[]},{"id":"fence-unlocked","say":"A fence now runs along the right edge. Set Height Mode to Unlocked and the right wing target higher.","why":"At field edges, a wing kept higher than the centre stays clear of fences and posts.","figure":"NX1458243","draft":false,"confirm":["Unlocked, right wing higher"]},{"id":"breakaway-stop","say":"The left boom end clipped a post and swung back. Stop: lever back to neutral.","why":"Always come to a complete stop before you reverse direction.","figure":"N136441","draft":false,"confirm":[]},{"id":"breakaway-clear","say":"Back away from the post until the boom swings back into place. Nobody stands in front of it.","why":"The breakaway is under hydraulic pressure; if it must be helped over an object, stand behind it.","figure":"N136441","draft":false,"confirm":["Boom back in position"]}]},{"title":"5. Practice: fold for transport","mode":"practice","checkpoint":false,"steps":[{"id":"p-park","say":"Done in this field. Stop and put the lever in PARK before you fold.","why":"The boom only folds below 8 km/h (5 mph) with the Transport Lock off.","figure":"N166477","draft":true,"confirm":[]},{"id":"p-look","say":"Look up and around again: no overhead wires, nobody near the boom.","why":"The same checks apply to folding as to unfolding.","figure":"N107858","draft":false,"confirm":["Clear to fold"]},{"id":"p-fold","say":"Fold for transport: floor switch and Centre boom raise until the boom is folded in and down in the cradles.","why":"Release both switches only once the boom is lowered into the cradles.","figure":"N153424","draft":false,"confirm":[]},{"id":"p-cradle","say":"It stopped above the cradles at its Return to Height point. Foot off, press Centre boom lower again.","why":"Transporting with the boom not lowered onto its cradles can damage the machine.","figure":"N153021","draft":false,"confirm":[]},{"id":"p-transport-lock","say":"Press Transport Lock: its indicator lights and the boom can't move on the road.","why":"Transport Lock blocks boom movements and spray on/off for road travel.","figure":"N120615","draft":false,"confirm":["Transport Lock indicator on"]}]}]},{"id":"612r-field-spraying","title":"Start spraying right: rates, sections, HMS headlands and AutoTrac","minutes":16,"objective":"Start the first pass in the manual's order (boom to height, solution pump, rate, move off, AutoTrac, sections, master), index sections off for a waterway, change rate on the move, run a headland with HMS in the right order and resume AutoTrac, then do the next headland by hand with HMS off.","trainer":"612R at the start of the first pass. Boom unfolded with the centre frame raised, engine at high idle, lever out of the park slot in neutral, park brake released, speed wheel 8 clicks up, wheel straight, solution pump OFF, master OFF. Display: Target Rate/Rx presets set from the product label (Rate 1 = this field's rate, Rate 3 = heavy-patch rate), guidance line set and Steer On, Return to Height set. HMS ON and Ready: Entering Headlands = Master Spray OFF and Boom Return to Height - Raise; Exiting Headlands = Boom Return to Height - Lower (Master Spray ON and AutoTrac Resume not ticked). Before section 4, turn HMS OFF on the display.","sections":[{"title":"1. Start spraying in the manual's order","mode":"learn","checkpoint":false,"steps":[{"id":"boom-height","say":"First pass. Lower the boom to spraying height with Centre boom lower.","why":"Field Operation step 1: the boom goes to operating height before the pump and the master.","figure":"N155116","draft":false,"confirm":[]},{"id":"pump-on","say":"Press Solution Pump to engage the pump. Its light comes on.","why":"Field Operation step 4. If no flow is detected, the pump shuts itself off to protect its seals.","figure":"N155117","draft":false,"confirm":[]},{"id":"rate-1","say":"Press Rate 1, this field's preset. Check it is highlighted on the display.","why":"Field Operation step 6: the rate switch picks a programmed target rate; the rate is then controlled automatically.","figure":"N155118","draft":false,"confirm":[]},{"id":"move-off","say":"Push the multi-function lever slowly forward to start moving.","why":"Field Operation step 7. Spraying starts on the move, so get moving before the master.","figure":"N166439","draft":false,"confirm":[]},{"id":"autotrac-on","say":"You're on the guidance line with Steer On shown. Press AutoTrac Resume so AutoTrac steers.","why":"Resume activates AutoTrac if heading is within 80\u00b0 of the track below 17.7 km/h (11 mph) and you're seated.","figure":"N155449","draft":true,"confirm":[]},{"id":"sections-ready","say":"Check the display: every boom section you need shows Section Ready.","why":"Field Operation step 8: verify the sections are enabled. Ready means enabled but not applying yet.","figure":"N119616","draft":false,"confirm":["All sections show Ready"]},{"id":"master-on","say":"Now press the master switch to start spraying while you keep moving.","why":"Field Operation step 9. Spray start-up is not immediate: press it moving forward, just before solution is needed.","figure":"N167055","draft":false,"confirm":[]}]},{"title":"2. Sections and rate on the move","mode":"learn","checkpoint":false,"steps":[{"id":"waterway","say":"An angled waterway is coming in from the left. Shut off the left-hand outer section.","why":"IBS Right shuts sections off starting at the left-hand end; IBS Left starts at the right-hand end.","figure":"N155496","draft":false,"confirm":[]},{"id":"sections-back","say":"Past the waterway. Turn the shut-off sections back on, all at once.","why":"IBS Reset restarts all shut-off sections that are enabled; IBS Left would bring them back one at a time.","figure":"N153020","draft":false,"confirm":[]},{"id":"rate-heavy","say":"Heavy weed patch ahead. Press Rate 3, this job's heavy-patch preset, without stopping.","why":"Presets 1, 2 and 3 are set in Target Rate/Rx; the selected rate is then controlled automatically.","figure":"N155118","draft":true,"confirm":[]},{"id":"rate-back","say":"Out of the patch. Press Rate 1 to go back to this field's rate.","why":"The selected rate is highlighted on the display: check Rate 1 is lit again.","figure":"N155118","draft":true,"confirm":[]}]},{"title":"3. Headland with HMS, in the right order","mode":"learn","checkpoint":false,"steps":[{"id":"hms-ready","say":"Headland coming. First check the HMS status on the run page shows Ready (green).","why":"Ready means HMS can be activated. With HMS OFF (gray), nothing changes when you press it.","figure":"WZ1405506","draft":false,"confirm":["HMS shows Ready (green)"]},{"id":"hms-entry","say":"At the headland: turn the speed wheel down 4 clicks and press HMS as you slow.","why":"Spray shutdown isn't immediate, so switch off while slowing. HMS turns Master Spray off and raises the boom.","figure":"N152638","draft":true,"confirm":[]},{"id":"turn","say":"Turn onto the next pass, then straighten the wheel.","why":"AutoTrac does not turn at the end of a track: you steer. Turning the wheel past 30\u00b0 switches AutoTrac off.","figure":"N151293","draft":true,"confirm":[]},{"id":"hms-exit","say":"Lined up on the new pass. Press HMS to run the exit and lower the boom.","why":"HMS exit is set to Return to Height - Lower. Get the boom back to height before you spray.","figure":"N152638","draft":true,"confirm":[]},{"id":"autotrac-resume","say":"Press AutoTrac Resume so AutoTrac steers this pass.","why":"Turning the wheel switched AutoTrac off. Resume works with heading within 80\u00b0 of the track below 17.7 km/h (11 mph).","figure":"N155449","draft":true,"confirm":[]},{"id":"spray-again","say":"Boom at height, AutoTrac steering: press the master switch to spray again.","why":"Field Operation step 11: when aligned with the next row, press the master to resume spraying.","figure":"N155121","draft":false,"confirm":[]},{"id":"speed-up","say":"Back to field speed: turn the speed wheel up 4 clicks.","why":"Rotating the wheel changes target speed. Pressing it swaps between Field 1 and Field 2 instead.","figure":"N152647","draft":false,"confirm":[]}]},{"title":"4. Practice: the next headland with HMS off","mode":"practice","checkpoint":false,"steps":[{"id":"p-entry","say":"Next headland. HMS shows OFF (gray), so do it by hand: slow down, master off, raise the boom.","why":"With HMS OFF nothing changes when you press it. Do its jobs yourself, before you turn.","figure":"N153021","draft":true,"confirm":[]},{"id":"p-turn","say":"Turn onto the next pass and straighten up.","why":"You steer at the end of the track; AutoTrac is off once the wheel turns past 30\u00b0.","figure":"N151293","draft":true,"confirm":[]},{"id":"p-exit","say":"On the new pass: lower the boom, resume AutoTrac, then spray.","why":"Boom back at operating height before the master. With Return to Height, the boom stops at its set point.","figure":"N153021","draft":true,"confirm":[]},{"id":"p-rate-speed","say":"Heavy patch at the start of this pass: select Rate 3, then turn the speed wheel up 4 clicks.","why":"The rate controller holds the target rate, within a tolerance, while you change speed.","figure":"N155118","draft":true,"confirm":[]}]}]},{"id":"612r-no-spray-fault","title":"No spray or the wrong rate: find the fault and recover","minutes":19,"objective":"Take over a 612R that has stopped spraying: stop safely, match the symptom to the manual's Solution Control System table, rule out the cab causes in order, relieve boom pressure the manual's way before touching any plumbing, open the valve that was left closed, restart and verify, then handle a faulted ExactApply nozzle with the same discipline.","trainer":"612R with Solution Command (single solution) and ExactApply. Boom unfolded at spraying height, engine at LOW idle, solution pump on, master on, lever out of park and forward, speed wheel 6 clicks up, wheel straight, Rate 2 = this job's preset. Tell the trainee: the display shows zero pressure while spraying, and the day operator cleaned the pressure strainers at lunch. Hidden fault 1: the strainer/flowmeter shutoff valve was left closed (handle across the hose). Tank has solution, target speed is in field range. Hidden fault 2 (section 4): after the restart one section shows Section Fault; Nozzle Turret | Status reports a stuck plunger on one nozzle body.","sections":[{"title":"1. Stop and read the symptom","mode":"learn","checkpoint":false,"steps":[{"id":"stop-spraying","say":"Zero pressure on the display while spraying. Press the master switch to stop spraying first.","why":"Master off closes the boom valves. Find the fault with spraying stopped.","figure":"N155121","draft":true,"confirm":[]},{"id":"stop-machine","say":"Slowly bring the multi-function lever back into the PARK position.","why":"Never service or adjust a machine while it is moving. In PARK the park brakes apply automatically.","figure":"N166477","draft":false,"confirm":[]},{"id":"name-symptom","say":"Open the manual's Solution Control System troubleshooting table. Find the symptom that matches.","why":"The table lists every cause the manual knows for each symptom, each with its fix.","figure":null,"draft":false,"confirm":["Zero pressure with the spray system operating"]}]},{"title":"2. Rule out the cab checks first","mode":"learn","checkpoint":false,"steps":[{"id":"tank-level","say":"First cause listed: solution tank empty. Check the level on the tank's sight gauge.","why":"The displayed tank volume is not the actual volume. Always verify it on the sight gauge.","figure":"N167217","draft":false,"confirm":["Tank has solution"]},{"id":"field-range","say":"Next cause: spraying in transport range. Check the corner post: is the target speed in field range?","why":"612R with wet system: field range 8.1\u201440 km/h (5\u201425 mph), transport range 41\u201456 km/h (26\u201435 mph).","figure":"NX1396836","draft":false,"confirm":["Target speed is in field range"]},{"id":"high-idle","say":"The engine is at low idle. Press High Idle to rule out low engine speed.","why":"The next table, Low pressure reading, starts with low engine speed: operate the engine at high idle.","figure":"N137031","draft":false,"confirm":[]},{"id":"rate-check","say":"Check the rate: press Rate 2, this job's preset, and see it highlighted on the display.","why":"Field Operation step 6: select the programmed rate (1, 2 or 3); the selected rate is highlighted.","figure":"N155118","draft":true,"confirm":[]},{"id":"suspect","say":"Cab causes ruled out. The day operator cleaned the pressure strainers at lunch. Which table cause fits?","why":"Strainer cleaning starts by closing the flowmeter shutoff valve; 'Flowmeter shutoff valve closed' is a zero-pressure cause.","figure":"NX1432687","draft":true,"confirm":["Suspect: strainer/flowmeter shutoff valve left closed"]}]},{"title":"3. Relieve pressure, then fix","mode":"learn","checkpoint":false,"steps":[{"id":"relief-on","say":"Before you touch any plumbing: on the display, turn Pressure Relief on in the Spray System app.","why":"The machine's decal: spray system is under pressure; conduct boom pressure relief before servicing.","figure":"N118056","draft":false,"confirm":["Pressure Relief enabled"]},{"id":"relief-pump-off","say":"Pressure Relief step 2: press Solution Pump to turn the pump off.","why":"Pressure Relief bleeds the pressure trapped in the boom out through the nozzles, with the pump off.","figure":"N120497","draft":false,"confirm":[]},{"id":"relief-boom-up","say":"Step 3: raise the boom centre frame to its highest position with Centre boom raise.","why":"The manual's Pressure Relief raises the centre frame fully before the section valves open.","figure":"N152641","draft":false,"confirm":[]},{"id":"relief-pressure","say":"Step 4: check the display shows solution system pressure of 27 kPa (0.27 bar) (4 psi).","why":"Pressure Relief step 4: verify this pressure before you open the section valves.","figure":null,"draft":false,"confirm":["Pressure reads 27 kPa (4 psi)"]},{"id":"relief-sections","say":"Step 5: on the Boom Sections tab, select Enable All.","why":"Enable All puts every section valve under the master switch, which opens them in step 6.","figure":"N118006","draft":false,"confirm":["Enable All selected"]},{"id":"relief-master","say":"Step 6: press the master switch. The section valves open for 6 seconds, then close.","why":"This releases the trapped boom pressure through the nozzles; the valves close by themselves after 6 seconds.","figure":"N120251","draft":false,"confirm":[]},{"id":"secure","say":"Before you leave the cab: press Low Idle, then turn the key to OFF and take it out.","why":"Stop the engine and secure the machine before service. After working load, idle at least 2 minutes first.","figure":"N166477","draft":false,"confirm":["Key OFF and removed"]},{"id":"open-valve","say":"Gloves and eyewear on. At the strainer/flowmeter shutoff valve, turn the handle parallel to the hose.","why":"Across the hose is closed, parallel is open. 'Flowmeter shutoff valve closed: open valve' is in the zero-pressure table.","figure":"NX1432687","draft":false,"confirm":["Valve was closed; now open"]}]},{"title":"4. Restart, verify, and a second fault","mode":"practice","checkpoint":false,"steps":[{"id":"restart","say":"Back in the seat, engine started: High Idle, Centre boom lower to height, then Solution Pump on.","why":"Field Operation order: boom at operating height, then the pump. High idle rules out low engine speed.","figure":"N155116","draft":true,"confirm":[]},{"id":"move-and-spray","say":"Out of park, lever slowly forward, then the master. Watch the pressure come up.","why":"Field Operation steps 7 and 9: get moving first, then press the master just before solution is needed.","figure":"N167055","draft":false,"confirm":[]},{"id":"fault-stop","say":"Pressure is back, but one section shows Section Fault. Master off, then lever back into PARK.","why":"Section Fault: that section is not applying, a nozzle fault has occurred. Stop and find it.","figure":"N122954","draft":true,"confirm":[]},{"id":"fault-find","say":"Nozzle System app: open Nozzle Turret | Status, pick the faulted section, and turn on Light Faulted Turrets.","why":"The status page shows each nozzle body's fault; Light Faulted Turrets flashes the faulted bodies on the boom.","figure":"WZ1408744","draft":false,"confirm":["Faulted nozzle found: stuck plunger"]},{"id":"fault-relieve","say":"The fix opens the nozzle body. Relieve pressure again: pump off, centre frame to the top, then master.","why":"Repair Nozzle Solenoid step 1: perform a pressure relief procedure before servicing the nozzle body.","figure":"N118056","draft":false,"confirm":[]},{"id":"fault-clean","say":"Low Idle, key off and out. Then disassemble that nozzle's cartridge, clean it and reassemble.","why":"For a stuck plunger the manual says: disassemble the cartridge assembly, clean, and reassemble.","figure":"WZ675761","draft":false,"confirm":["Cartridge cleaned and reassembled"]},{"id":"fault-verify","say":"Restart and check: High Idle, boom down, pump on, move off, master. Every section should show Applying.","why":"Section Applying means that section is spraying. Verify the fix before you carry on.","figure":"N119617","draft":true,"confirm":["Every section shows Applying"]}]}]},{"id":"612r-full-shift","title":"A full spraying day on the 612R: from daily checks to parked and rinsed","minutes":107,"objective":"Run a whole shift on the 612R in the manual's order: daily checks, start-up, road transport, filling and loading chemical, unfolding and spraying, headlands with HMS, sections and rates, a high-pressure fault with boom pressure relief, rinsing, folding, transport back and parking safely. Then pass a no-hints assessment of the key in-cab sequence.","trainer":"Yard, start of the day: machine parked on level ground, lever in Park, engine off (real rig), boom folded on its cradles, tread at narrowest, Transport Lock OFF, park brake switch engaged by the last operator, solution tank empty and rinsed, ladder down, game camera view 1. Section 7: tell the trainee the display shows a high pressure reading and the rate won't hold (two plugged tips on the left wing). Resuming at a checkpoint: 2 = as above; 3 = engine running, Auto selected; 4 = parked at the field fill spot, boom folded, Transport Lock on, ladder up; 5 = tank filled, pump and agitation on; 6 and 7 = spraying on the move with HMS set up; 8 = spraying, tank nearly empty; 9 = boom folded, parked, engine running.","sections":[{"title":"1. Daily and prestarting checks","mode":"learn","checkpoint":true,"steps":[{"id":"s1-parked","say":"Start of the day. Check the machine is on level ground, lever in Park, engine off and key out.","why":"Daily checks are made parked on level ground with the engine stopped and the key removed.","figure":"N155095","draft":false,"confirm":["Level, parked, engine off, key out"]},{"id":"s1-mirrors","say":"Adjust the rear view mirrors. Use the left-hand landing for the left mirror; never stand on the fuel tank.","why":"Standing on the fuel tank risks a serious fall.","figure":"N155107","draft":false,"confirm":["Mirrors adjusted"]},{"id":"s1-engine-bay","say":"Check the engine compartment for trash, especially around the turbocharger, exhaust manifold and muffler.","why":"Debris gathers at these hot spots; never steam clean or pour cold water on a hot injection pump.","figure":null,"draft":false,"confirm":["Engine compartment clean"]},{"id":"s1-engine-oil","say":"Check engine oil: wipe the dipstick, refit the cap fully, then read the level between ADD and FULL.","why":"Never run the engine below the ADD mark, and don't overfill.","figure":"N153905","draft":false,"confirm":["Engine oil between ADD and FULL"]},{"id":"s1-water-separator","say":"Drain water from the fuel water separator: unthread the drain valve on the primary filter completely.","why":"The valve must drop about 12 mm (0.5 in) to drain the water properly.","figure":"N153302","draft":false,"confirm":["Water separator drained"]},{"id":"s1-coolant","say":"Check coolant in the overflow tank sight tube: between the HOT LEVEL and COLD LEVEL marks.","why":"Which mark applies depends on engine temperature; if low, look for leaks first.","figure":"N99187","draft":false,"confirm":["Coolant between HOT and COLD marks"]},{"id":"s1-hydraulic-oil","say":"Check hydraulic oil in the sight tube against the fill-level decal for the current oil temperature.","why":"Read it level, tread narrow, booms in the cradles, engine stopped; drive and hydraulics share this oil.","figure":"N153001","draft":false,"confirm":["Hydraulic oil at the right level"]},{"id":"s1-fuel","say":"With the engine off, lower the fuel fill ladder and fill the fuel tank with the proper diesel fuel.","why":"Shut off the engine before refuelling; never stand on the fuel tank.","figure":"N155102","draft":false,"confirm":["Fuel tank filled"]},{"id":"s1-def","say":"Top up the DEF tank through a clean funnel, then tighten the cap. Never put DEF in the fuel tank.","why":"Fill DEF every time you refuel; never mix up DEF and diesel fuel.","figure":"N153002","draft":false,"confirm":["DEF topped up"]},{"id":"s1-tires","say":"Inspect the tires. Check inflation pressures and loads against the Wheels and Tires section.","why":"The manual's tire tables set the pressures and loads for each tire.","figure":null,"draft":false,"confirm":["Tires inspected"]},{"id":"s1-air-springs","say":"Clean any dirt or debris from around each air spring, including between the rubber and the piston.","why":"Dirt and debris collecting around an air spring can damage it.","figure":"NX1432694","draft":false,"confirm":["Air springs clear"]},{"id":"s1-grease-suspension","say":"Grease the suspension fittings with John Deere SD polyurea grease only: five pumps at each fitting.","why":"Other greases can wear the suspension components early.","figure":"NX1432685","draft":false,"confirm":["Suspension greased"]},{"id":"s1-grease-boom-pins","say":"Grease the boom lift arm pivots: front fittings, grease bank and rear fitting, on both sides.","why":"The manual calls for this every day with John Deere SD polyurea grease.","figure":"N102003","draft":false,"confirm":["Boom lift arm pins greased"]},{"id":"s1-air-tanks","say":"Wearing eye protection, open the valve on the onboard air tank and drain the moisture.","why":"The unloader valve and tank exhaust are at high pressure.","figure":"N153004","draft":false,"confirm":["Air tank drained"]},{"id":"s1-strainers-prep","say":"Pressure strainers: put on protective clothing, eyewear and gloves, then close the flowmeter shutoff valve.","why":"The pump must be off: closing this valve with the pump running traps pressure.","figure":"NX1432687","draft":false,"confirm":["PPE on, flowmeter shutoff valve closed"]},{"id":"s1-strainers-clean","say":"Drain the strainers into a container, wash the screens with clean water, refit them, then reopen the valves.","why":"Clean screens keep dirt out of the pump and nozzles; never drain solution onto the ground.","figure":"N99945","draft":false,"confirm":["Strainers clean, valves reopened"]}]},{"title":"2. Start up and set up the cab","mode":"learn","checkpoint":true,"steps":[{"id":"s2-climb-in","say":"Climb into the cab facing the machine, keeping three-point contact with the steps and handholds.","why":"Most falls happen getting on and off; never jump down.","figure":"T133468","draft":false,"confirm":["In the seat"]},{"id":"s2-seat-belt","say":"Fasten the seat belt: latch it, listen for the click, tug it, then snug it across your hips.","why":"The seat belt protects you from crushing injury in a rollover.","figure":"N152675","draft":false,"confirm":["Seat belt fastened"]},{"id":"s2-armrest","say":"Set the CommandARM: loosen the knobs, slide the console to suit you, then tighten the knobs.","why":"You will work the multi-function lever all day; set it within easy reach.","figure":"N166438","draft":false,"confirm":["Armrest console set"]},{"id":"s2-start","say":"Lever in Park? Sound the horn, turn the key to Run, then to Start. Release it when the engine starts.","why":"The horn clears people away; start only from the seat with the lever in Park.","figure":"H127222","draft":false,"confirm":["Engine running"]},{"id":"s2-warm-up","say":"Let it idle at about 900 rpm with no load for 1\u20142 minutes. Watch coolant temperature on the corner post.","why":"Protect the turbocharger: stay below 1000 rpm until normal idle is established.","figure":"NX1396826","draft":false,"confirm":["Warm-up idle done"]},{"id":"s2-steer-warm","say":"While it warms, turn the steering wheel left and right until it turns freely.","why":"Cycling the steering circulates warm hydraulic fluid.","figure":"N151293","draft":false,"confirm":[]},{"id":"s2-auto-mode","say":"On the display, open the Transmission application and select Auto mode.","why":"The machine always starts in Manual mode until Auto is selected and High Idle is pressed.","figure":"N142909","draft":false,"confirm":["Auto mode selected"]},{"id":"s2-display-check","say":"Check the display settings: rates, tank volume, minimum and spray-off pressure, sections, nozzle spacing, spray width.","why":"Before Field Operation lists these display settings to verify before you go.","figure":"H129095","draft":false,"confirm":["Display settings checked"]}]},{"title":"3. Drive to the field","mode":"learn","checkpoint":true,"steps":[{"id":"s3-smv-lights","say":"Check the SMV emblem is on, then press Road Lights and Hazard Lights. Check the amber lights flash.","why":"Public roads need the SMV emblem and working lights; keep them clean and visible.","figure":"N153023","draft":false,"confirm":["SMV in place, road and hazard lights on"]},{"id":"s3-tread-boom","say":"Check the tread is at its narrowest and the boom is folded down onto its cradles.","why":"Transport only at the narrowest tread; travelling with booms off the cradles can damage the machine.","figure":"N153424","draft":false,"confirm":["Tread narrowest, boom on cradles"]},{"id":"s3-transport-lock","say":"Press the Transport Lock switch. Its light comes on.","why":"Transport Lock blocks spraying, boom movements and tread adjust on the road.","figure":"N120615","draft":false,"confirm":["Transport lock on"]},{"id":"s3-high-idle","say":"Press High Idle for maximum engine speed.","why":"Transport needs full engine speed; High Idle also completes Auto mode.","figure":"N137031","draft":false,"confirm":[]},{"id":"s3-park-brake","say":"Press the Park Brake switch to release the park brakes before you move the lever.","why":"Last night's operator engaged it, and it never releases by itself.","figure":"N137032","draft":false,"confirm":[]},{"id":"s3-ladder","say":"Raise the ladder with the Ladder Up/Down switch. On the 612R it also rises by itself as you drive off.","why":"The ladder rises automatically on the real machine; the simulator needs the switch.","figure":"N151287","draft":true,"confirm":[]},{"id":"s3-rephase","say":"Rephase the steering: creep forward, full left lock plus three turns, then full right lock plus three turns.","why":"Rephasing the steering system is required before road transport.","figure":"N151293","draft":true,"confirm":[]},{"id":"s3-road-speed","say":"Press the speed wheel to select Field 2, then roll it up to your road target speed.","why":"Field 1 is capped at field speed. Never above 48 km/h (30 mph) unless the application system is empty.","figure":"N152647","draft":false,"confirm":[]},{"id":"s3-arrive","say":"At the field's fill spot: pull the lever back to slow and stop, then put it in Park.","why":"The lever is the primary brake; stop slowly to avoid nose-diving.","figure":"N166476","draft":false,"confirm":[]}]},{"title":"4. Fill and load chemical","mode":"learn","checkpoint":true,"steps":[{"id":"s4-label-site","say":"Read the chemical label and put on its PPE. Fill where runoff can't reach water, livestock, gardens or people.","why":"Label directions govern safe, legal use of the chemical.","figure":null,"draft":false,"confirm":["Label read, PPE on, fill site safe"]},{"id":"s4-prime","say":"The tank is empty: prime the solution pump with a low-volume rinse cycle, and end it once primed.","why":"Running the solution pump dry damages it.","figure":"NX1435130","draft":false,"confirm":["Pump primed"]},{"id":"s4-connect","say":"Check the Quik-Fill valve is closed, remove the cap, connect the nurse hose and close the lock levers.","why":"The Quik-Fill valve can hold hazardous material; check it is closed before the cap comes off.","figure":"NX1435337","draft":false,"confirm":["Nurse hose connected"]},{"id":"s4-start-fill","say":"Open the nurse tank valve. Press Pull-On Fill, open the Quik-Fill valve, then select Tank Auto Fill.","why":"Keep the nurse tank water at or above the pump's midline for the whole fill.","figure":"NX1435136","draft":false,"confirm":["Auto fill running"]},{"id":"s4-eductor-on","say":"Lower the eductor and raise its lid. When the tank is at least half full, press Eductor On/Off.","why":"Starting the eductor before half full makes the chemical foam.","figure":"NX1435325","draft":false,"confirm":["Eductor on, tank at least half full"]},{"id":"s4-load","say":"Open the eductor sump valve, then the rinse valve. Pour in the chemical; rinse each container on the rinse nozzle.","why":"Follow the label for how much product to add.","figure":"N135935","draft":false,"confirm":["Chemical loaded, containers rinsed"]},{"id":"s4-eductor-off","say":"When the eductor is empty: close the rinse and sump valves, close the lid, raise it, press Eductor On/Off.","why":"Verify the eductor is empty before you close it up.","figure":"N98892","draft":false,"confirm":["Eductor empty and stowed"]},{"id":"s4-finish-fill","say":"Auto fill stops at the upper level switches. Close the nurse and Quik-Fill valves, remove the hose, refit the cap.","why":"A closed Quik-Fill valve is the first check before spraying.","figure":"NX1435340","draft":false,"confirm":["Fill finished, Quik-Fill closed"]},{"id":"s4-clean-water","say":"Check the clean water tank on the left-hand side is filled with clean water.","why":"It supplies clean rinse water for in-field cleaning.","figure":"N153569","draft":false,"confirm":["Clean water tank full"]},{"id":"s4-agitate","say":"PPE off, back in the cab: press Solution Pump, then Agitation, to mix the tank.","why":"Agitation needs the solution pump running first.","figure":"N120490","draft":true,"confirm":["Agitation on"]}]},{"title":"5. Unfold and start spraying","mode":"learn","checkpoint":true,"steps":[{"id":"s5-conditions","say":"Check the wind: don't spray above 16 km/h (10 mph) or toward a sensitive crop, garden or populated area.","why":"Minimise drift; the product label may set tighter limits.","figure":null,"draft":false,"confirm":["Wind OK for spraying"]},{"id":"s5-lock-off","say":"Press the Transport Lock switch again so its light goes out.","why":"With Transport Lock on, the boom won't fold, unfold, raise or tilt and spraying is blocked.","figure":"N120615","draft":false,"confirm":["Transport lock off"]},{"id":"s5-field1","say":"Press the speed wheel back to Field 1, then roll it down to the lowest target speed.","why":"Tread adjust starts from the lowest target speed; Field 1 holds you to field speed.","figure":"N118483","draft":false,"confirm":[]},{"id":"s5-tread-out","say":"Set tread for the row spacing: creep forward, hold Tread OUT to the width you want, then stop in Park.","why":"Tread adjust works only on the move, 1 through 8 km/h (1 and 5 mph), with Transport Lock off.","figure":"N120614","draft":false,"confirm":["Tread set for the rows"]},{"id":"s5-clear","say":"Before unfolding: check nobody is near the boom and there is enough space on both sides.","why":"Spray booms move quickly; only unfold where there is enough room.","figure":"N152955C","draft":false,"confirm":["Boom area clear"]},{"id":"s5-unfold","say":"Hold the boom fold floor switch, then press and hold Centre boom lower until both sides fully unfold.","why":"With the floor switch held, Centre boom lower unfolds instead of lowering.","figure":"N153423","draft":false,"confirm":[]},{"id":"s5-boom-height","say":"Release both switches. Lower the boom to spraying height, then lower each wing to height.","why":"Centre frame first, then each wing with its own tilt switch.","figure":"N155116","draft":false,"confirm":[]},{"id":"s5-rth","say":"On the Boom System page: enable Return to Height, choose the height mode, then press Set to Current.","why":"HMS uses Return to Height to raise and lower the boom at headlands.","figure":"N153021","draft":false,"confirm":["Return to Height set"]},{"id":"s5-hms-setup","say":"HMS setup. Entering: Speed, Master Spray OFF, Return to Height - Raise. Exiting: Speed, Master Spray ON, Return to Height - Lower.","why":"HMS only switches what you select. Its status indicator must show Ready (green).","figure":"WZ1406688","draft":false,"confirm":["HMS ready (green)"]},{"id":"s5-high-idle","say":"Check the Solution Pump light is still on, then press High Idle.","why":"Auto mode needs High Idle; the pump has been running since you mixed the tank.","figure":"N137031","draft":false,"confirm":[]},{"id":"s5-rate","say":"Select rate switch 1, programmed for this field's product. Check it is highlighted on the display.","why":"With a rate switch selected the system controls the rate to that preset automatically.","figure":"N155118","draft":false,"confirm":[]},{"id":"s5-drive-off","say":"Roll the speed wheel up to spraying speed, take the lever out of Park and push it slowly forward.","why":"Field Operation: get moving first, then spray.","figure":"N166439","draft":false,"confirm":[]},{"id":"s5-master-on","say":"Moving on the line: press the Spray System On/Off (master) switch. Watch rate and pressure on the display.","why":"Start-up isn't instant: press it while moving, just before solution is needed.","figure":"N167055","draft":false,"confirm":[]}]},{"title":"6. Practice: passes, headlands, sections and rates","mode":"practice","checkpoint":true,"steps":[{"id":"s6-hms-in-1","say":"Headland ahead. Press HMS: spraying stops, the boom rises and the speed drops.","why":"Spray off while slowing for the row end; HMS does it with one switch.","figure":"WZ1406325","draft":false,"confirm":[]},{"id":"s6-turn-1","say":"Turn left onto the next pass, then straighten up.","why":"HMS only switches what you set it to; the steering is yours.","figure":"N151293","draft":true,"confirm":[]},{"id":"s6-hms-out-1","say":"Lined up on the new pass: press HMS to exit. The boom lowers, and spraying and speed resume.","why":"One press runs your Exiting Headlands settings.","figure":"WZ1406327","draft":false,"confirm":[]},{"id":"s6-ibs-right","say":"Waterway on the left: press IBS Right once per section to shut sections off from the left end.","why":"IBS shuts sections off in sequence without taking your hand off the lever.","figure":"N153020","draft":false,"confirm":[]},{"id":"s6-ibs-reset","say":"Past the waterway: press IBS Reset to turn all the shut-off sections back on.","why":"IBS Reset restarts every shut-off section that is enabled.","figure":"N153020","draft":false,"confirm":[]},{"id":"s6-rate-2","say":"This part of the field needs preset 2. Select rate switch 2 without stopping.","why":"Stopped with the spray on, the pump holds minimum pressure and over-applies.","figure":"N124435","draft":false,"confirm":[]},{"id":"s6-wing","say":"The ground rises under the right wing. Raise the right wing, then lower it again once you are past.","why":"Each wing has its own tilt switch.","figure":"N152643","draft":true,"confirm":[]},{"id":"s6-hms-in-2","say":"Next headland: press HMS to enter it.","why":"Spray off and boom up before the turn.","figure":"WZ1406325","draft":false,"confirm":[]},{"id":"s6-turn-2","say":"Turn right this time onto the next pass, then straighten up.","why":"Alternate turns keep you working back and forth across the field.","figure":"N151293","draft":true,"confirm":[]},{"id":"s6-hms-out-2","say":"On the new pass: press HMS to exit the headland.","why":"Boom down, spray on and speed back, as you set it up.","figure":"WZ1406327","draft":false,"confirm":[]},{"id":"s6-quick-stop","say":"Someone walks toward the boom! Press Quick Stop, and pull the lever back to stop the machine.","why":"Quick Stop shuts off pump, spraying and wet system valves; stopping the machine is up to you.","figure":"N152634","draft":true,"confirm":[]},{"id":"s6-recover","say":"All clear. Restart: Solution Pump on, lever forward, then the master switch.","why":"Quick Stop turned the pump off; nothing reaches the nozzles until it runs again.","figure":"N155117","draft":true,"confirm":[]}]},{"title":"7. Mid-shift fault: high pressure, rate won't hold","mode":"learn","checkpoint":true,"steps":[{"id":"s7-master-off","say":"The display shows high pressure and the rate won't hold. Press the master switch to stop spraying.","why":"Spray off before you stop, or the pump holds minimum pressure and over-applies where you stand.","figure":"N155121","draft":false,"confirm":[]},{"id":"s7-stop","say":"Pull the lever back to stop, then put it in Park.","why":"In Park the park brakes apply automatically.","figure":"N166477","draft":false,"confirm":[]},{"id":"s7-diagnose","say":"In Troubleshooting, find 'High pressure reading during spraying operation'. Which causes can you check yourself?","why":"The table lists each problem with its solution; some solutions are for your dealer.","figure":null,"draft":false,"confirm":["Check nozzles and boom strainers"]},{"id":"s7-pr-enable","say":"Before anyone opens a nozzle: on the Spray System page, enable Pressure Relief.","why":"Pressure Relief bleeds the pressure trapped in the boom.","figure":"N118056","draft":false,"confirm":["Pressure Relief enabled"]},{"id":"s7-pump-off","say":"Press the Solution Pump switch to turn the pump OFF.","why":"Step 2 of Pressure Relief: the pump must be off.","figure":"N120497","draft":false,"confirm":[]},{"id":"s7-boom-top","say":"Press Centre boom raise until the boom centre frame is at its highest position.","why":"Step 3 of Pressure Relief.","figure":"N152641","draft":false,"confirm":[]},{"id":"s7-check-4psi","say":"Check the display shows 27 kPa (0.27 bar) (4 psi), and that all boom sections are enabled.","why":"Steps 4 and 5 of Pressure Relief.","figure":"WZ1408770","draft":false,"confirm":["27 kPa (4 psi), all sections enabled"]},{"id":"s7-relief","say":"Press the Spray System Master switch. The section valves open for 6 seconds, then close.","why":"That bleeds the trapped pressure out through the nozzles.","figure":"N120251","draft":false,"confirm":[]},{"id":"s7-shutdown","say":"Lower the boom, press Low Idle, then stop the engine and take the key.","why":"Before working on the machine: lower equipment, stop the engine and secure the machine.","figure":"N166477","draft":false,"confirm":["Engine off, key out"]},{"id":"s7-remove-tips","say":"In PPE, find the plugged tips on the boom and remove them over a container.","why":"Catch the solution in a suitable container, never on the ground.","figure":"N118272","draft":false,"confirm":["Plugged tips removed"]},{"id":"s7-clean-tips","say":"Clean the chemical deposits off, refit everything and check for leaks.","why":"Never put a nozzle tip to your mouth to clear it; keep spare tips to swap in.","figure":"N118272","draft":false,"confirm":["Tips clean, refitted, no leaks"]},{"id":"s7-restart","say":"PPE off before you climb in. Lever in Park, sound the horn and start the engine.","why":"Start only from the seat, with the lever in Park.","figure":"H127222","draft":false,"confirm":["Engine running"]},{"id":"s7-idle-pump","say":"Press High Idle and reselect Auto mode, then press Solution Pump to turn the pump back on.","why":"After a restart the machine is in Manual mode until High Idle is pressed and Auto is selected.","figure":"N137031","draft":false,"confirm":[]},{"id":"s7-boom-back","say":"Raise the boom, then press and hold Centre boom lower: it stops at your Return to Height setting.","why":"With Return to Height on, the boom stops at the set point as it lowers.","figure":"N153021","draft":false,"confirm":[]},{"id":"s7-verify","say":"Drive forward, then spray. Check pressure and rate are steady now.","why":"If the pressure still reads high, the boom in-line strainers are next on the list.","figure":"N167055","draft":true,"confirm":["Pressure normal, rate holding"]}]},{"title":"8. Finish: rinse, fold, drive back and park","mode":"learn","checkpoint":true,"steps":[{"id":"s8-stop-end","say":"The tank is empty at the end of the field. Spray off with the master, then stop and park.","why":"Spray off before you stop, or you puddle what's left where you stop.","figure":"N155121","draft":false,"confirm":[]},{"id":"s8-rinse-start","say":"Rinse System: choose Solution System, rinse cycles and fluid usage. Pump OFF, then select Start.","why":"Rinse daily; the tank must be empty and the pump off when you press Start.","figure":"WZ1406733","draft":false,"confirm":["Solution System rinse started"]},{"id":"s8-rinse-spray","say":"Press the Solution Pump switch, then the Spray System Master switch: rinse water sprays through the boom.","why":"Steps 9 and 10 of the Solution System rinse.","figure":"N120251C","draft":false,"confirm":[]},{"id":"s8-rinse-off","say":"When the rinse water has sprayed out: master off, then pump off. Then select Done.","why":"Turn off the spray system and the solution pump when the tank runs empty.","figure":"N119467C","draft":true,"confirm":["Done selected"]},{"id":"s8-boom-only","say":"Now a Boom Only rinse: select Boom Only, check the sections are enabled, then select Start.","why":"A Solution System rinse ends with a Boom Only rinse; Start begins pump priming.","figure":"N151087","draft":false,"confirm":["Boom Only rinse started"]},{"id":"s8-boom-rinse","say":"Press the Solution Pump switch, then the master switch. Wait for the boom rinse complete message.","why":"Steps 5 to 7 of the Boom Only rinse.","figure":"N120497C","draft":false,"confirm":["Boom rinse complete"]},{"id":"s8-aspirators","say":"In PPE, close every nozzle body that is not on an aspirator, and set the aspirator nozzles open.","why":"Chemical builds up in the aspirators if they aren't cleaned out regularly.","figure":"N118272","draft":false,"confirm":["Nozzle bodies closed, aspirators open"]},{"id":"s8-second-rinse","say":"Start a second boom rinse. Flush one section at a time, 5\u201410 seconds each, using the section scroll wheels.","why":"All sections at once may not give enough pressure to flush the boom plumbing.","figure":"N151298","draft":false,"confirm":["Every section flushed"]},{"id":"s8-nozzles-back","say":"Rinse done: master off, pump off. Then return the nozzle bodies to their previous positions.","why":"Leave the boom ready for the next job.","figure":"N118272","draft":true,"confirm":["Nozzle bodies back in place"]},{"id":"s8-fold","say":"Area clear: hold the floor switch and Centre boom raise until the boom folds into its cradles.","why":"Booms move quickly; fold below 8 km/h (5 mph) with Transport Lock off.","figure":"N153424","draft":false,"confirm":[]},{"id":"s8-tread-in","say":"Narrow the tread for the road: creep forward, hold Tread IN to the narrowest setting, then stop in Park.","why":"Always use the narrowest tread on the road; tread adjust works only on the move.","figure":"N120613","draft":false,"confirm":["Tread at narrowest"]},{"id":"s8-road-ready","say":"Road Lights and Hazard Lights on, then press Transport Lock so its light comes on.","why":"Lights for the road; Transport Lock blocks spraying and boom moves on the road.","figure":"N153023","draft":false,"confirm":["Road and hazard lights on","Transport lock on"]},{"id":"s8-rephase","say":"Rephase the steering again: creep forward, full left lock plus three turns, then full right plus three turns.","why":"Rephasing the steering system is required before every road transport.","figure":"N151293","draft":true,"confirm":[]},{"id":"s8-drive-home","say":"Press the speed wheel for Field 2, roll it up to road speed, and drive back to the yard.","why":"The tank is empty and rinsed; never exceed the maximum transport speed.","figure":"N152647","draft":false,"confirm":[]},{"id":"s8-park","say":"In the yard: slowly return the lever to Park, then press Low Idle.","why":"Park the Machine, steps 1 and 2: the park brakes apply in Park.","figure":"N166477","draft":false,"confirm":[]},{"id":"s8-shutdown","say":"Lights and accessories off. Idle at least 2 minutes, then key OFF and out. Lower the ladder.","why":"Idling cools the hot engine parts after a day at working load.","figure":"N166477","draft":false,"confirm":["Lights off, idled 2 minutes, key out"]},{"id":"s8-battery","say":"If you switch the battery off for the night, first wait until the LED at the battery switch goes out.","why":"The DEF lines purge after shutdown; cut power early and DEF can crystallise or freeze in them.","figure":"N153287","draft":false,"confirm":["Battery LED off before switching off"]}]},{"title":"9. Assessment: the in-cab sequence, no hints","mode":"assess","checkpoint":true,"steps":[{"id":"a-unfold","say":"Assessment, new field: engine running, Transport Lock off, tank filled. Unfold the boom.","why":"No hints from here: the key in-cab sequence on your own.","figure":"N153423","draft":false,"confirm":[]},{"id":"a-height","say":"Lower the boom and both wings to spraying height.","why":"Set height before you spray.","figure":"N155116","draft":false,"confirm":[]},{"id":"a-ready","say":"Get ready to spray: solution pump and engine speed.","why":"Pump and High Idle before you move.","figure":"N155117","draft":false,"confirm":[]},{"id":"a-spray","say":"Start the pass and start spraying.","why":"Move first, then spray.","figure":"N167055","draft":false,"confirm":[]},{"id":"a-hms-in","say":"Headland. Enter it.","why":"One switch: spray off, boom up, speed down.","figure":"WZ1406325","draft":false,"confirm":[]},{"id":"a-turn","say":"Turn onto the next pass and line up.","why":"The steering is yours; HMS handles the rest.","figure":"N151293","draft":true,"confirm":[]},{"id":"a-hms-out","say":"On the new pass: leave the headland.","why":"One switch: boom down, spray on, speed back.","figure":"WZ1406327","draft":false,"confirm":[]},{"id":"a-stop","say":"End of the field: stop spraying and park.","why":"Spray off before you stop.","figure":"N155121","draft":false,"confirm":[]},{"id":"a-pump-off","say":"Shut the solution pump off.","why":"Nothing more to spray here.","figure":"N120497","draft":false,"confirm":[]},{"id":"a-fold","say":"Fold the boom for transport.","why":"Floor switch and Centre boom raise, into the cradles.","figure":"N153424","draft":false,"confirm":[]}]}]}];
